/* The Pioneer — Act I: The Making (1891–1924).
   Spine after Ellen Wilkinson (the player holds her place): Chorlton-on-Medlock, the Wesleyan chapel,
   the scholarship ladder, the ILP at sixteen, Manchester University, the suffrage organiser, the
   co-operative employees' union, the Communist Party, Gorton ward and Middlesbrough East in 1924.
   Routes chosen at "Sixteen" (1907): medicine (Edith Summerskill: the medical school, the war
   hospitals, clean milk), the Liberal office (Megan Lloyd George and Eleanor Rathbone: the People's
   Budget, National Insurance, the Liberal split, family endowment) and the Conservative house
   (Thelma Cazalet-Keir and Mavis Tate: the Primrose League, war welfare work, Mrs Aster's Plymouth
   campaign of 1919, the LCC).
   Owner's rule (10 Nov 2026): no man/woman choice. The life is written so it reads either way; the
   flag `woman` comes from the quiz (TM.readsAsWoman) or from choices here (joining the WSPU, which
   took only women). Woman-specific variants later in the camp are gated on `!woman`.
   Sources: RESEARCH.md section I (re-read 11 Nov 2026); docs/camps/pioneer.md. */
(function () {
  const TM = (window.TM = window.TM || {});
  TM.ACTS = TM.ACTS || {};
  TM.ACTS.pioneer = TM.ACTS.pioneer || {};

  TM.PEOPLE = Object.assign(TM.PEOPLE || {}, {
    rathmore: { name: 'Eleanor Rathmore', role: 'A Liverpool reformer of a great shipowning family' },
    aster: { name: 'Mrs Nancy Aster', role: 'A Virginian hostess married into vast English money' },
    pankridge: { name: 'Christabel Pankridge', role: 'Leader of the militant suffragettes' },
    pollard: { name: 'Harry Pollard', role: 'A boilermaker and Communist organiser' },
  });

  const MAN = TM.PION_MAN = '~!route-doctor ~!route-liberal ~!route-tory';
  TM.VARDEF = Object.assign(TM.VARDEF || {}, { pioneer: { city: 'Manchester', seat: 'Middlesbrough East', party: 'Labour', council: 'Manchester City Council' } });
  const SET = {
    doctor: 'set:city=London set:seat=Fulham_West set:party=Labour set:council=Middlesex_County_Council',
    liberal: 'set:city=Liverpool set:seat=Anglesey set:party=Liberal set:council=Liverpool_City_Council',
    tory: 'set:city=London set:seat=Islington_East set:party=Conservative set:council=the_London_County_Council',
  };

  TM.FORKS = TM.FORKS || {};
  TM.FORKS.cpgb24 = {
    title: 'The Party member',
    history: 'In 1924, when the Labour Party barred Communists from standing as its candidates, one of the most gifted young organisers in the North chose the Communist Party. She, or he, never sat in Parliament. There were years in Moscow, at the Red International of Labour Unions, and years in British jails after the General Strike, and a slow, bitter disillusion in the thirties as old comrades disappeared in Stalin\'s purges.',
    more: [],
    real: 'Ellen Wilkinson, a founder member of the Communist Party in 1920, left it in 1924 when Labour proscribed dual membership, and was elected Labour Member for Middlesbrough East that October.',
    ends: { 1: { head: 'The comrade', text: '1924. {first} {last} is {age}, a full-time organiser for the Communist Party, with a card in one pocket and a ticket to Moscow in the other. The Labour Party will not have {first} back.' } },
  };

  TM.ACTS.pioneer[1] = {
    title: 'Act I · The Making',
    span: '1891–1924',
    regen: 3,
    intro: 'You were born in October 1891 at 41 Coral Street, Chorlton-on-Medlock, in a terrace of red brick a mile from the Manchester cotton exchange. Your father worked in the mills and now sells insurance door to door; he is a Wesleyan Methodist and a reader of anything he can borrow. Your mother is often ill. The family is poor, and determined not to stay that way. You are small, quick, red-haired and nine years old.',
    end: (s) => ({ head: s.flags.includes('mp') ? 'The Member for {seat}' : 'Thirty-three', text: '1924. {first} {last} is ' + (s.year - s.born) + '. ' + (s.flags.includes('mp') ? 'One of a handful of women in the House, or one of a great many men who got there by an odd road: either way, a newcomer the old Members watch with suspicion.' : 'A life of meetings, committees and causes behind; the House of Commons still ahead, or never.') }),
    start: {
      born: 1891,
      year: 1901,
      effects: 'cap-2 fav-6 press-6 rep-6 money-30 health-4',
      rel: {
        father: { name: 'Your father', role: 'Insurance agent, Wesleyan, self-taught', score: 60, status: 'Proud of you, worried about money.' },
        mother: { name: 'Your mother', role: 'Often ill', score: 55, status: 'Wants you to be safe.' },
      },
    },

    scenes: [
      /* ═══════ Everyday politics of a Manchester childhood ═══════ */
      { id: 'queen-1901', year: 1901, title: 'The old Queen',
        venue: { plate: 'city', label: 'The Wesleyan chapel, Chorlton-on-Medlock' },
        text: 'January 1901. The Queen is dead, after sixty-three years, and the chapel is draped in black. The minister preaches on the Empire, on the soldiers in South Africa, and on duty. The Sunday school superintendent asks the children to sign the temperance pledge in her memory. Your father, who reads the Manchester Guardian, mutters that the war in South Africa is a disgrace. Everyone heard him.',
        basis: 'The death of Queen Victoria, 22 January 1901, during the South African War; Wilkinson\'s Wesleyan upbringing and the chapel\'s temperance culture.',
        real: 'Queen Victoria died on 22 January 1901. The Manchester Guardian, under C. P. Scott, opposed the South African War. Ellen Wilkinson grew up in a Wesleyan Methodist family. The details of this scene are invented.',
        check: 'research', facts: ['wilkinson-early'],
        choices: [
          { label: 'Sign the pledge', effects: 'order+2 loyalty+2 #chapel', historical: true,
            result: 'You write your name in the book in your best copperplate. The superintendent says you have a good hand and a clear head. You will keep the pledge longer than most.',
            diary: 'Signed the pledge. A good hand, he said.' },
          { label: 'Ask the minister why the war is a disgrace', effects: 'temper+2 cap+1 @father+3',
            result: 'The minister is not pleased. Your father, walking home, explains the concentration camps for the Boer women and children. You are nine and you do not sleep that night.',
            diary: 'The camps in Africa. Father explained.' },
          { label: 'Slip out to watch the soldiers drill', effects: 'empire+2 order+1',
            result: 'The Volunteers are drilling in the street, and a sergeant lets you hold his rifle. It is heavier than you thought.',
            diary: 'Held a rifle. Heavy.' },
        ] },

      { id: 'rates-1903', year: 1903, title: 'Passive resistance',
        venue: { plate: 'city', label: 'The magistrates\' court, Manchester' },
        text: 'Spring 1903. The new Education Act makes ratepayers pay for Church of England and Catholic schools, and thousands of Nonconformists are refusing to pay that part of their rates. Your father is one of them. The bailiffs have taken the parlour clock to sell at auction, and today he is in front of the magistrates. He has asked whether you want to come and watch. Your mother says a court is no place for a child.',
        basis: 'The Nonconformist "passive resistance" campaign against the Education Act 1902, in which thousands refused the school rate and had goods distrained.',
        real: 'The Education Act 1902 put Church schools on the rates. Many Nonconformists refused to pay; tens of thousands were summonsed and some jailed. The campaign helped the Liberal landslide of 1906. Whether Wilkinson\'s father took part is not recorded; the scene is invented.',
        check: 'research', facts: ['passive-resistance'],
        choices: [
          { label: 'Go and sit in the gallery', effects: 'temper+2 state+1 @father+5', historical: true,
            result: 'Your father tells the magistrates he will pay for schools but not for catechisms. They fine him. The chapel buys the clock back at the auction and hands it to your mother. You learn that a law can be refused, if enough people refuse it.',
            diary: 'Father in court. The chapel bought back the clock.' },
          { label: 'Stay home with your mother', effects: 'loyalty+2 @mother+5',
            result: 'You sit with her while she frets. When your father comes back he is cheerful: fined, and famous in the chapel. Your mother says fame does not pay the rent.',
            diary: 'Stayed with Mother. Father fined, and cheerful.' },
          { label: 'Ask your teacher what she thinks', effects: 'cap+2 order+1',
            result: 'Your teacher, a Church woman, says the law is the law. She also says you are the cleverest child in the class, and should sit for a scholarship.',
            diary: 'The law is the law. And a scholarship.' },
        ] },

      { id: 'free-trade-hall-1905', year: 1905, title: 'Will the Liberal government?',
        venue: { plate: 'ballroom', label: 'The Free Trade Hall, Manchester' },
        text: 'Friday, 13 October 1905. The Free Trade Hall is packed for Sir Edward Gray and Mr Winstan Churchward, the Liberals who expect to govern after the election. You have squeezed into the gallery. Two young women stand up and unfurl a banner: Votes for Women. One asks whether a Liberal government will give women the vote. Nobody answers. The stewards drag them out, and the police are waiting.',
        basis: 'The Free Trade Hall meeting of 13 October 1905, at which Christabel Pankhurst and Annie Kenney of the WSPU questioned Sir Edward Grey, were ejected and arrested, and chose prison rather than pay their fines.',
        real: 'At the Free Trade Hall on 13 October 1905 Christabel Pankhurst and Annie Kenney asked Sir Edward Grey whether a Liberal government would give women the vote. They were thrown out and arrested, and chose jail over fines: the beginning of militant suffrage. Churchill was also on the platform.',
        check: 'research', facts: ['free-trade-hall-1905'],
        choices: [
          { label: 'Follow them out and join them', effects: 'temper+3 order-2 press+1 !woman #suffragette @pankridge+8',
            result: 'You find them outside the police court the next morning and ask how to join. Their Women\'s Social and Political Union takes women only, and now it has you. Your mother is horrified.',
            diary: 'Joined the WSPU. Mother horrified.' },
          { label: 'Shout for the women from the gallery', effects: 'temper+2 press+1 order-1', historical: true,
            result: 'You shout "Answer her!" until a steward takes you by the collar. Outside, in the rain, you decide that whoever wins the election, you will not be quiet.',
            diary: 'Shouted "Answer her!" Thrown out. Will not be quiet.' },
          { label: 'Stay, and listen to Mr Churchward', effects: 'order+1 cap+2',
            result: 'He is brilliant, rude and very young. He talks about free trade for an hour and never once mentions the women. You notice that.',
            diary: 'Churchward. Brilliant. Never mentioned the women.' },
        ] },

      { id: 'election-1906-pion', year: 1906, title: 'Manchester turns',
        venue: { plate: 'city', label: 'Albert Square, Manchester' },
        text: 'January 1906. The Prime Minister himself, Mr Arthur Belford, has lost his seat in Manchester East, and the whole city has gone Liberal, with a Labour man or two. Albert Square is full of people waiting for the results to go up on the Town Hall. You are fourteen and have spent three weeks addressing envelopes for the Liberals and selling the Labour Leader for the ILP. Both sides claim you.',
        basis: 'The general election of January 1906, in which Balfour lost Manchester East and the Liberals swept Manchester; Labour won 29 seats nationally.',
        real: 'Balfour lost Manchester East in January 1906 in the Liberal landslide; the Liberals took almost every Manchester seat, and Churchill won Manchester North West. Labour won 29 seats across the country.',
        check: 'research', facts: ['election-1906-labour', 'manchester-1906'],
        choices: [
          { label: 'Cheer the Labour men loudest', effects: 'state+2 loyalty-1 @father+2', historical: true,
            result: 'A Labour man has won at Gorton. You cheer until you are hoarse, and an ILP man in a red tie gives you a pamphlet on the right to work.',
            diary: 'Labour won Gorton! A pamphlet.' },
          { label: 'Stand with the Liberals: they will do the work', effects: 'order+1 cap+2',
            result: 'The Liberal agent thanks you for the envelopes and says there will be work for clever young people in the new government\'s causes. He takes your name.',
            diary: 'The Liberal agent took my name.' },
          { label: 'Go home and read', effects: 'cap+3',
            result: 'You read the election results in the Guardian the next morning, columns of them, and work out the swing in every seat with a pencil. Nobody asked you to.',
            diary: 'Worked out the swing. Nobody asked.' },
        ] },

      { id: 'meals-1906', year: 1906, title: 'The hungry child',
        venue: { plate: 'school', label: 'Ardwick Higher Elementary Grade School' },
        text: 'Autumn 1906. You won a scholarship to this school at eleven, and now you help the teacher with the little ones. A girl of seven in your class faints at her desk; she has had nothing to eat since yesterday. A new Act lets councils feed hungry schoolchildren, but Manchester has not decided whether to use it. Some councillors say feeding children will sap their parents\' independence.',
        basis: 'The Education (Provision of Meals) Act 1906, which allowed local authorities to provide school meals; Wilkinson won a scholarship to Ardwick Higher Elementary Grade School at eleven.',
        real: 'The Education (Provision of Meals) Act 1906 let councils feed needy schoolchildren but did not compel them; many were slow to act. Wilkinson won a scholarship at eleven to Ardwick Higher Elementary Grade School and later trained as a teacher.',
        check: 'research', facts: ['school-meals-1906', 'wilkinson-early'],
        choices: [
          { label: 'Write to the education committee', effects: 'cap+2 state+2 press+1', historical: true,
            result: 'Your letter, in your best hand, is read out at the committee and mocked by one councillor. The chairman says it is the best argument he has heard. Manchester starts a scheme the next year.',
            diary: 'My letter read out. Mocked. Then a scheme.' },
          { label: 'Share your own dinner, every day', effects: 'state+1 health-2 rep+1',
            result: 'You split your bread and dripping with her every day for a term. You are hungry yourself by four o\'clock. She does not faint again.',
            diary: 'Half my dinner. She did not faint again.' },
          { label: 'Take her home to her mother', effects: 'state+1 temper+1',
            result: 'Her mother is a widow taking in washing, with four children and no fire. You walk home slowly, thinking about what independence means.',
            diary: 'Her mother. No fire. Independence.' },
        ] },

      /* ═══════ The fork ═══════ */
      { id: 'sixteen-1907', year: 1907, title: 'Sixteen',
        venue: { plate: 'city', label: 'The ILP rooms, Longsight' },
        text: 'Autumn 1907. You are sixteen, with a bursary to train as a teacher and a head full of ideas. Tonight at the Longsight ILP a speaker said socialism is the only answer. The Liberal agent from 1906 has offered you a place in his office. A doctor at the dispensary says you could win a scholarship to a medical school in London. A wealthy Conservative lady you met at a bazaar wants a clever secretary.',
        basis: 'A fork invented for the camp (docs/camps/pioneer.md). Wilkinson joined the Longsight ILP at sixteen and trained as a teacher before winning a history scholarship to Manchester University; the other routes follow Edith Summerskill (medicine), Megan Lloyd George and Eleanor Rathbone (Liberal), and Thelma Cazalet-Keir and Mavis Tate (Conservative).',
        real: 'Ellen Wilkinson joined the Independent Labour Party at sixteen, trained as a pupil teacher on a bursary, and in 1910 won a scholarship to Manchester University. Summerskill trained as a doctor, Megan Lloyd George entered politics as a Liberal, and Cazalet-Keir and Tate as Conservatives, by very different roads.',
        check: 'research', facts: ['wilkinson-early', 'summerskill-early', 'megan-early', 'cazalet-early'],
        choices: [
          { label: 'Join the ILP and aim for the university', effects: 'state+3 cap+2 !route-manchester', historical: true,
            result: 'You pay your penny and sign the card. You will teach by day, study by night, and speak on street corners in between. The university is three years away, if you can win it.',
            diary: 'Joined the ILP. The university next.' },
          { label: 'Medicine, in London', effects: 'cap+4 money-3 @mother+3 !route-doctor ' + SET.doctor,
            roll: { stat: 'capital', diff: 30,
              pass: { effects: 'rep+2', result: 'You win the scholarship. In two years you will go up to London to study medicine, one of very few from a terrace like yours.', diary: 'A medical scholarship! London.' },
              fail: { effects: 'money-1', result: 'You miss it narrowly, but the dispensary doctor pays for a year\'s cramming, and you win it the next year.', diary: 'Missed it. A year\'s cramming, then won.' } } },
          { label: 'The Liberal office', effects: 'order+1 cap+2 fav+2 !route-liberal ' + SET.liberal,
            result: 'The agent sends you to a Liberal reformer in Liverpool who needs someone quick with figures: a woman of a great shipowning family, Miss Eleanor Rathmore, who is studying the docks.',
            diary: 'Liverpool. Miss Rathmore. The docks.' },
          { label: 'The Conservative lady\'s secretary', effects: 'order+2 money+3 empire+2 !route-tory ' + SET.tory,
            result: 'You go to London as secretary to a rich widow with a house in Kensington and a seat on every committee of the Primrose League. Your father does not speak to you for a month.',
            diary: 'Kensington. The Primrose League. Father silent.' },
        ] },

      /* ═══════ Manchester: the Wilkinson spine ═══════ */
      { id: 'university-1910', year: 1910, title: 'The Jones Scholarship', if: MAN,
        venue: { plate: 'school', label: 'Owens College, Manchester University' },
        text: 'October 1910. You have won the Jones Open History Scholarship to Manchester University, and you are the first in your family to set foot in a university. The other students have fathers who are mill-owners and solicitors. The university Fabian Society wants you on its committee; the ILP wants you on its platforms; your tutor wants you in the library. There are not enough hours.',
        basis: 'Wilkinson won the Jones Open History Scholarship to Manchester University in 1910 and took her BA in 1913, while active in the university socialist societies.',
        real: 'Wilkinson entered Manchester University in 1910 on the Jones Open History Scholarship and graduated in 1913 with an upper second. She was active in the Fabian Society and the ILP while there.',
        check: 'research', facts: ['wilkinson-early'],
        choices: [
          { label: 'Do everything, and sleep less', effects: 'cap+3 state+2 health-3 press+1', historical: true,
            result: 'You run the Fabians, speak for the ILP on Sundays and take an upper second. You are thin, tired and happier than you have ever been.',
            diary: 'Upper second. Thin. Happy.' },
          { label: 'The library first', effects: 'cap+5 order+1',
            result: 'You take a first and your tutor talks of research. The ILP sees less of you.',
            diary: 'A first. Research, he says.' },
          { label: 'The platforms first', effects: 'press+4 state+2 temper+2 cap-1',
            result: 'You become the best young speaker in Manchester, and scrape a third. Your tutor is disappointed; the crowds are not.',
            diary: 'A third. The crowds don\'t care.' },
        ] },

      { id: 'pilgrimage-1913', year: 1913, title: 'The Pilgrimage', if: MAN,
        venue: { plate: 'city', label: 'The road to London' },
        text: 'July 1913. You are a paid organiser for the National Union of Women\'s Suffrage Societies, the law-abiding wing of the movement, and you are marching the Pilgrimage: women walking from every corner of England to Hyde Park, to show the government that suffrage is not only smashed windows. In a Midlands market town the crowd has turned ugly. Someone has thrown a dead rat at the banner. You have the platform.',
        basis: 'The NUWSS Suffrage Pilgrimage of June–July 1913; Wilkinson became a paid NUWSS organiser in June 1913 and helped organise the Pilgrimage.',
        real: 'In the summer of 1913 thousands of NUWSS supporters walked to London on the Suffrage Pilgrimage, ending in a rally of some 50,000 in Hyde Park on 26 July. Marchers were often abused and attacked on the road. Wilkinson was a paid NUWSS organiser from June 1913.',
        check: 'research', facts: ['wilkinson-early', 'pilgrimage-1913'],
        choices: [
          { label: 'Speak on, and win them round', effects: 'press+4 steel+2 #orator', historical: true,
            roll: { stat: 'press', diff: 25,
              pass: { effects: 'rep+3', result: 'You make them laugh at the man with the rat. By the end half the market is applauding. You learn that a hostile crowd is only a crowd you have not yet won.', diary: 'Won the market. The rat man laughed at.' },
              fail: { effects: 'health-3 rep+1', result: 'A clod of earth catches you on the temple. You finish the speech with blood on your collar, and the local paper is suddenly on your side.', diary: 'Blood on my collar. The paper on our side.' } } },
          { label: 'Fold the banner and march on', effects: 'order+2 loyalty+1',
            result: 'You move the column on to the next town without a fight. Nobody is hurt. Nobody is converted.',
            diary: 'Marched on. Nobody hurt. Nobody won.' },
          { label: 'Send for the police', effects: 'order+3 temper-1 state-1',
            result: 'The constable clears the market. The marchers are safe, and the town decides that suffragists need policemen.',
            diary: 'The police. Safe, and resented.' },
        ] },

      { id: 'organiser-1915', year: 1915, title: 'Equal pay for the shell girls', if: MAN,
        venue: { plate: 'mill', label: 'A co-operative warehouse, Manchester' },
        text: 'July 1915. The war has taken the men, and women are doing their jobs in the shops and warehouses of the co-operative movement at a third less pay. You are the new national organiser of the Amalgamated Union of Co-operative Employees, at a wage, with a bicycle and a railway pass. The men in the union fear that cheap women will take their jobs for good. The women want equal pay.',
        basis: 'Wilkinson became national women\'s organiser of the Amalgamated Union of Co-operative Employees in July 1915 and campaigned for equal pay for women doing men\'s work.',
        real: 'Wilkinson was appointed an organiser for the Amalgamated Union of Co-operative Employees in 1915; it became part of NUDAW in 1921. She campaigned for equal pay for women brought in during the war.',
        check: 'research', facts: ['wilkinson-early'],
        choices: [
          { label: 'Demand the rate for the job, for everyone', effects: 'state+2 steel+2 @members+5', historical: true,
            result: 'You convince the men that equal pay protects their rates too, and the co-operative societies, shamed, concede in a dozen towns. The women join the union in hundreds.',
            diary: 'The rate for the job. Hundreds joined.' },
          { label: 'Settle for war bonuses now', effects: 'order+2 fav+2',
            result: 'You win a war bonus for the women and leave the principle for later. Later never quite comes.',
            diary: 'War bonuses. The principle later.' },
          { label: 'Strike one warehouse as an example', effects: 'temper+3 steel+3 order-2 press+2',
            roll: { stat: 'press', diff: 45,
              pass: { effects: 'rep+3 @members+6', result: 'Three days and the society gives in. Every co-operative in the North takes notice.', diary: 'Three days. They gave in.' },
              fail: { effects: 'rep-2', result: 'The newspapers call it a strike against the war effort. The society holds out and the women drift back.', diary: 'Against the war effort, they said. Lost.' } } },
        ] },

      { id: 'communist-1920', year: 1920, title: 'Founder member', if: MAN,
        venue: { plate: 'city', label: 'The Cannon Street Hotel, London' },
        text: 'July 1920. Russia has had its revolution and survived. In a London hotel the British socialists are founding a Communist Party, and you have come with half the Manchester left. Harry Pollard, a boilermaker, says the Labour Party is finished and the future belongs to Moscow. The Labour Party says no member of the new party may stand as Labour. You love Labour. You also want a revolution.',
        basis: 'The founding of the Communist Party of Great Britain in the summer of 1920, of which Wilkinson was a founder member.',
        real: 'The CPGB was founded at the Cannon Street Hotel in London on 31 July – 1 August 1920. Wilkinson was a founder member and visited Moscow in 1921. She left the party in 1924, when Labour barred Communists from its candidates\' lists.',
        check: 'research', facts: ['wilkinson-cpgb'],
        choices: [
          { label: 'Join, and keep your Labour card', effects: 'state+3 order-3 loyalty-2 !cpgb', historical: true,
            result: 'You join both, as many do for now. In 1921 you go to Moscow for the trade union international, and come back excited and uneasy.',
            diary: 'Both cards. Moscow. Excited, uneasy.' },
          { label: 'Stay in Labour only', effects: 'loyalty+3 fav+3 state+1',
            result: 'You tell Pollard you will make the revolution through the ballot box. He says you will find the box empty.',
            diary: 'Labour only. Pollard scornful.' },
          { label: 'Join, and give up Labour', effects: 'state+4 order-4 loyalty-4 !cpgb !cpgb-only',
            result: 'You tear up your Labour card in front of the hall. The cheering is loud. Some of your Manchester friends do not cheer.',
            diary: 'Tore up the Labour card.' },
        ] },

      { id: 'gorton-1923', year: 1923, title: 'Gorton ward', if: MAN,
        venue: { plate: 'whitehall', label: 'Manchester Town Hall' },
        text: 'November 1923. You have won a seat on Manchester City Council for Gorton, and in December you stand for Parliament at Ashton-under-Lyne. Your first committee is public health: slum clearance, the fever hospital, the milk supply. The Tory chairman has given you the job nobody wants: the report on the back-to-back houses of Ancoats. Nobody expects the new member to read it.',
        basis: 'Wilkinson was elected to Manchester City Council for Gorton in November 1923, serving until 1926, and fought Ashton-under-Lyne in December 1923.',
        real: 'Wilkinson sat on Manchester City Council for Gorton from 1923 to 1926. She finished third at Ashton-under-Lyne in the general election of December 1923.',
        check: 'research', facts: ['wilkinson-early'],
        choices: [
          { label: 'Read it all, and walk every street', effects: 'cap+4 state+2 health-1', historical: true,
            result: 'You walk Ancoats with the sanitary inspector for a fortnight and rewrite the report with photographs. The council clears six streets. At Ashton in December you come third, but the papers have heard of you.',
            diary: 'Ancoats. Six streets cleared. Third at Ashton.' },
          { label: 'Concentrate on Ashton', effects: 'press+3 cap+1',
            result: 'You give the campaign everything and come a strong third. The council report is late, and the chairman says so in public.',
            diary: 'A strong third. The report late.' },
          { label: 'Make the report a political weapon', effects: 'press+4 temper+2 fav-3',
            result: 'You leak it to the Manchester Guardian before the committee sees it. The slums are on every breakfast table, and the Tories never trust you again.',
            diary: 'Leaked it. Every breakfast table.' },
        ] },

      { id: 'middlesbrough-1924', year: 1924, title: 'Middlesbrough East', if: MAN,
        venue: { plate: 'mill', label: 'A committee room, Middlesbrough' },
        text: 'October 1924. The first Labour government has fallen after nine months, and the Labour Party has just ruled that no Communist may stand as its candidate. Middlesbrough East, a steel and shipbuilding seat, wants you, if you are clear of the Communists. Pollard says you will be betraying the revolution for a seat on the green benches. The Zinoviev letter is in every newspaper.',
        basis: 'Wilkinson left the Communist Party in 1924 when Labour barred Communists and won Middlesbrough East on 29 October 1924, by 927 votes, during the Zinoviev letter election.',
        real: 'Wilkinson left the CPGB in 1924 and was elected for Middlesbrough East on 29 October 1924 with a majority of 927, the only woman on the Labour benches in the new Parliament. The forged Zinoviev letter dominated the last days of the campaign.',
        check: 'research', facts: ['wilkinson-early', 'wilkinson-cpgb', 'zinoviev-1924'],
        choices: [
          { label: 'Leave the Party and fight the seat', effects: '-!cpgb loyalty+2 fav+3 health-2', historical: true,
            roll: { stat: 'press', diff: -15,
              pass: { effects: 'rep+5 seat+12 !mp office=Member_for_Middlesbrough_East', result: 'You win by nine hundred and twenty-seven votes, in an election where Labour loses forty seats. You go to Westminster as the Member for {seat}.', diary: 'Middlesbrough East! By 927. The Zinoviev election.' },
              fail: { effects: 'rep+1', result: 'The Red Letter scare sinks you by a few hundred. You go back to the union, and wait.', diary: 'The Red Letter. Lost by a few hundred.' } } },
          { label: 'Stay in the Party, and refuse the seat', effects: 'state+3 loyalty-6 fork=cpgb24',
            result: 'You tell Middlesbrough you will not abandon your comrades. They find another candidate. Pollard shakes your hand.',
            diary: 'Stayed with the Party. Pollard shook my hand.' },
          { label: 'Leave the Party, but stay in Manchester', effects: '-!cpgb loyalty+2 cap+2',
            result: 'You turn Middlesbrough down and keep your council seat and your union work. The House can wait.',
            diary: 'Stayed in Manchester. The House can wait.' },
        ] },

      /* ═══════ Medicine (the Summerskill route) ═══════ */
      { id: 'medschool-1910', year: 1910, title: 'The dissecting room', if: '!route-doctor',
        venue: { plate: 'sickroom', label: 'The London School of Medicine for Women, Hunter Street' },
        text: 'October 1910. The only medical school in London that will take you without question is the one founded for women; the great hospital schools mostly will not. The anatomy demonstrator is a woman surgeon who trained in Paris because London would not have her. Your first cadaver is a pauper from the workhouse infirmary, a woman of forty who looks seventy. Nobody claimed her body.',
        basis: 'Women\'s medical education before 1914: the London School of Medicine for Women was the main route; most London hospital schools excluded women until the war. Summerskill trained at King\'s College and Charing Cross, one of the earliest women admitted there.',
        real: 'Before the First World War most London medical schools refused women; the London School of Medicine for Women, attached to the Royal Free, trained most British women doctors. Several schools, including Charing Cross, opened to women during the war. Edith Summerskill qualified in 1924.',
        check: 'unchecked', facts: ['summerskill-early', 'lsmw'],
        choices: [
          { label: 'Learn everything the pauper\'s body can teach', effects: 'cap+4 steel+2', historical: true,
            result: 'You learn the body from her: the rickets in her bones, the scars of childbirth, the lungs of a mill-hand. You decide that medicine without politics is only half the job.',
            diary: 'The pauper woman. Rickets. Mill lungs.' },
          { label: 'Find out who she was', effects: 'state+3 temper+1',
            result: 'The workhouse records give a name, a mill, a dead husband and six children in the cottage homes. You go to see one of them, and do not know what to say.',
            diary: 'Her name. Six children. I said nothing useful.' },
          { label: 'Keep your head down and pass', effects: 'order+2 cap+2 money+1',
            result: 'You pass every examination at the first attempt and keep your opinions for later.',
            diary: 'Passed. Opinions later.' },
        ] },

      { id: 'war-hospital-1915', year: 1915, title: 'Endell Street', if: '!route-doctor',
        venue: { plate: 'sickroom', label: 'The Military Hospital, Endell Street, Covent Garden' },
        text: 'May 1915. A military hospital has opened in an old workhouse in Covent Garden, staffed and run entirely by women doctors under two suffragette surgeons, with five hundred beds for wounded soldiers. The War Office expected it to fail. You are a student dresser on the night shift. A convoy has come in from Ypres: gas cases, coughing their lungs up. There are not enough beds.',
        basis: 'The Endell Street Military Hospital, opened in May 1915 by Flora Murray and Louisa Garrett Anderson, staffed by women; a composite student\'s experience for the medical route.',
        real: 'Endell Street Military Hospital, run by the suffragist doctors Flora Murray and Louisa Garrett Anderson, treated about 26,000 patients between 1915 and 1919 and proved women could run a military hospital. The first German chlorine gas attacks came at Ypres in April 1915.',
        check: 'research', facts: ['endell-street'],
        choices: [
          { label: 'Work through the night, and the next', effects: 'cap+3 steel+2 health-4 rep+2', historical: true,
            result: 'You stay on your feet for thirty hours. By dawn you can tell from the sound of a cough which men will live. The surgeons notice you.',
            diary: 'Thirty hours. I can hear who will live.' },
          { label: 'Write to the papers about the gas', effects: 'press+4 state+2 fav-2',
            result: 'Your anonymous letter about the gas cases runs in the Manchester Guardian. The censor is furious; the Army Medical Department sends more beds.',
            diary: 'My letter. The censor furious. More beds.' },
          { label: 'Ask to go to France', effects: 'steel+3 empire+2 health-3',
            death: { chance: 0.02, text: 'You died of septicaemia in a casualty clearing station near Béthune in 1916, from a cut taken while operating. You were 24.', headline: 'A medical student dies in France' },
            result: 'You serve a year in a hospital near Béthune. You come home knowing more about wounds than any professor in London.',
            diary: 'Béthune. Wounds. Home.' },
        ] },

      { id: 'milk-1920', year: 1920, title: 'The milk', if: '!route-doctor',
        venue: { plate: 'sickroom', label: 'A child welfare clinic, Tottenham' },
        text: '1920. Qualified, married to a doctor, and working in a child welfare clinic in north London, you see the same thing every week: babies with tuberculosis of the bones and glands, from milk drawn from infected cows and sold unpasteurised in the open churn. The dairy trade says pasteurisation will ruin the farmers and destroy the goodness of the milk. The council\'s medical officer will not touch it.',
        basis: 'Summerskill\'s campaign for clean, tuberculin-tested and pasteurised milk, rooted in her work as a doctor in north London.',
        real: 'Bovine tuberculosis from untreated milk killed and crippled thousands of British children a year between the wars. Summerskill, a doctor in north London, campaigned for compulsory pasteurisation, which was resisted by the dairy trade and came only gradually.',
        check: 'unchecked', facts: ['summerskill-early', 'milk-tb'],
        choices: [
          { label: 'Stand for the council, and fight it there', effects: 'state+3 cap+2 fav+1', historical: true,
            result: 'You start canvassing in Green Lanes. A doctor who knocks on doors is a novelty. The dairymen put up a candidate against you.',
            diary: 'Canvassing in Green Lanes. The dairymen against me.' },
          { label: 'Publish the figures', effects: 'press+4 cap+2',
            result: 'Your paper on the clinic\'s cases appears in The Lancet and then in the Daily Herald. The dairy trade calls you a crank.',
            diary: 'The Lancet. A crank, says the trade.' },
          { label: 'Treat the children and leave politics alone', effects: 'order+2 health+1 money+3',
            result: 'You build a good practice. The children keep coming with the same disease.',
            diary: 'A good practice. The same disease.' },
        ] },

      /* ═══════ The Liberal office (Rathmore, Megan) ═══════ */
      { id: 'docks-1908', year: 1908, title: 'The docks inquiry', if: '!route-liberal',
        venue: { plate: 'mill', label: 'The Liverpool docks' },
        text: '1908. Miss Rathmore, a tall, shabby, formidable woman of a great shipowning family, is investigating how dock labourers live on casual work. She has you counting: hours stood at the stand waiting to be picked, days worked, shillings earned, what the wives buy. Her own family owns ships that use these men. She says what ought to be done can be done. You are not sure she knows what it costs.',
        basis: 'Eleanor Rathbone\'s study of casual dock labour in Liverpool (her report of 1903–04 and later work); her family motto, "What ought to be done, can be done."',
        real: 'Rathbone published an inquiry into the conditions of dock labour in Liverpool in 1904 and worked with her father on social questions. The family motto was "What ought to be done, can be done." The assistant here is invented.',
        check: 'research', facts: ['rathbone-early'],
        choices: [
          { label: 'Count everything, especially what the wives spend', effects: 'cap+4 state+2 @rathmore+8', historical: true,
            result: 'Your tables show that the wives feed the family on what is left after the men\'s beer and fares, and that the children go short first. Miss Rathmore reads them twice and says: the money should go to the mothers.',
            diary: 'The wives\' figures. Money to the mothers, she says.' },
          { label: 'Tell her what her family\'s ships pay', effects: 'temper+2 state+2 @rathmore-2',
            result: 'She goes white, and then thanks you. She takes the figures to her brother\'s firm. Nothing changes, but she never forgets you said it.',
            diary: 'Told her about her family\'s ships. She thanked me.' },
          { label: 'Organise the dockers into a union', effects: 'steel+3 state+2 order-2 @rathmore-4',
            result: 'You start talking to the men about a union. Miss Rathmore says investigation and agitation do not mix, and sends you back to the Liberal office.',
            diary: 'Talked union. Sent back.' },
        ] },

      { id: 'budget-1909', year: 1909, title: 'The People\'s Budget', if: '!route-liberal',
        venue: { plate: 'city', label: 'A Liberal meeting, Toxteth' },
        text: 'November 1909. The Lords have thrown out Mr Lloyd Gwynne\'s budget, with its taxes on land and great incomes to pay for old-age pensions and dreadnoughts. There will be an election in January: the Peers against the People. The Liberal agent wants speakers at every street corner in Liverpool. Your family are Labour people; the Liberals have never quite trusted a clever young person from a Manchester terrace.',
        basis: 'The rejection of the People\'s Budget by the House of Lords on 30 November 1909 and the general election of January 1910.',
        real: 'The House of Lords rejected Lloyd George\'s budget on 30 November 1909, breaking convention. The Liberals won the January 1910 election narrowly; the budget passed in April 1910, and the Parliament Act of 1911 curbed the Lords.',
        check: 'research', facts: ['peoples-budget'],
        choices: [
          { label: 'Speak every night: Peers against People', effects: 'press+4 state+2 #orator', historical: true,
            result: 'You discover you can hold a Liverpool street corner against Orangemen, Tory hecklers and the rain. The agent calls you the best speaker he has.',
            diary: 'Peers against People. Held the corner.' },
          { label: 'Write the leaflets', effects: 'cap+3 press+2',
            result: 'Your leaflet on what the land taxes mean for a Toxteth rent goes out in its tens of thousands.',
            diary: 'My leaflet. Tens of thousands.' },
          { label: 'Go back to Manchester and work for Labour', effects: 'state+3 loyalty+2 -!route-liberal !route-manchester set:city=Manchester set:seat=Middlesbrough_East set:party=Labour set:council=Manchester_City_Council',
            result: 'You decide the Liberals will never give the workers more than pensions and promises. You come home to the ILP.',
            diary: 'Home to the ILP.' },
        ] },

      { id: 'insurance-1912', year: 1912, title: 'Ninepence for fourpence', if: '!route-liberal',
        venue: { plate: 'whitehall', label: 'The Insurance Commission, Liverpool' },
        text: 'July 1912. The National Insurance Act comes into force, and the Liberals need people to explain it: fourpence a week from the worker, threepence from the employer, twopence from the state, for doctoring and sick pay. The doctors are threatening to boycott it. Housewives are told it will not cover them; the insurance covers only the earners. Miss Rathmore says it misses half the nation: the mothers.',
        basis: 'The National Insurance Act 1911, in force from July 1912, which covered workers but not their dependants; the doctors\' initial resistance; Rathbone\'s argument for support paid to mothers.',
        real: 'National Insurance health benefits began in January 1913, contributions in July 1912. Wives and children not in work were not covered for doctoring until the NHS in 1948. Rathbone developed the case for family allowances paid to mothers from about 1917.',
        check: 'research', facts: ['national-insurance-1911', 'rathbone-early'],
        choices: [
          { label: 'Explain it, and campaign to extend it', effects: 'state+3 cap+2 @rathmore+5', historical: true,
            result: 'You explain the stamps to a thousand meetings, and at every one somebody\'s wife asks why she is left out. You keep a list of them. It becomes a pamphlet.',
            diary: 'A thousand meetings. A list of the wives.' },
          { label: 'Join the Insurance Commission as an official', effects: 'order+3 money+4 cap+2',
            result: 'You become one of the new women inspectors, with a salary and a pension. Politics will have to wait.',
            diary: 'An inspector. A salary.' },
          { label: 'Organise the women who are left out', effects: 'state+3 temper+2 press+2',
            result: 'A Women\'s Insurance League, with you as secretary. The Liberal office is uneasy; it was meant to be selling the Act, not criticising it.',
            diary: 'The Women\'s Insurance League. The office uneasy.' },
        ] },

      { id: 'coupon-1918', year: 1918, title: 'The coupon', if: '!route-liberal',
        venue: { plate: 'city', label: 'A Liberal club, Liverpool' },
        text: 'December 1918. The war is won, women over thirty have the vote, and Mr Lloyd Gwynne is fighting the election in coalition with the Tories, handing a letter of approval, the coupon, to his own Liberals and denying it to Mr Askwith\'s. The Liberal Party is breaking in two. A Liberal seat across the Mersey wants a candidate. With the coupon you would likely win. Without it, you would lose.',
        basis: 'The "coupon" election of December 1918, in which Lloyd George and the Conservatives endorsed coalition candidates and the Asquithian Liberals were crushed.',
        real: 'In December 1918 the Lloyd George–Conservative coalition won a landslide; Liberals without the coupon were nearly wiped out, Asquith losing his own seat. Women over thirty voted for the first time, and Constance Markievicz was the first woman elected, though she did not take her seat.',
        check: 'research', facts: ['coupon-1918'],
        choices: [
          { label: 'Stay with Askwith, and lose honourably', effects: 'loyalty+3 state+1 rep+2', historical: true,
            result: 'You fight the seat without the coupon and lose by thousands. But the old Liberals remember who stood by them.',
            diary: 'No coupon. Lost. Remembered.' },
          { label: 'Take the coupon', effects: 'fav+4 loyalty-3 order+2',
            roll: { stat: 'favour', diff: 30,
              pass: { effects: '!mp seat+10 rep+3 set:seat=Birkenhead_East office=Member_for_Birkenhead_East', result: 'You win, one of the first newcomers of the new franchise in a House still almost all men. The old Liberals call you a coalition hack.', diary: 'Won with the coupon. A hack, they say.' },
              fail: { effects: 'rep-1', result: 'Even with the coupon you lose to a Labour man. The tide is turning.', diary: 'Lost even with the coupon.' } } },
          { label: 'Stand down and work for family endowment', effects: 'state+3 cap+2 @rathmore+6',
            result: 'You join Miss Rathmore\'s Family Endowment Committee: an allowance for every child, paid to the mother. It is the cause of your life, or it may be.',
            diary: 'Family endowment. Paid to the mother.' },
        ] },

      /* ═══════ The Conservative house (Cazenove-Kerr, Tatton) ═══════ */
      { id: 'primrose-1908', year: 1908, title: 'The Primrose League', if: '!route-tory',
        venue: { plate: 'ballroom', label: 'A drawing room in Kensington' },
        text: '1908. Your employer runs a habitation of the Primrose League, the Conservative association of dames and knights with its badges and fêtes, which has half a million members and more women than any party. Today\'s committee is planning a garden party for the Tariff Reform League. Your employer wants you to write the speeches. Her nephew, home from Oxford, says the whole thing is a joke. The members do not think so.',
        basis: 'The Primrose League, the mass Conservative organisation founded in 1883, in which upper-class and middle-class women did much of the work; a composite of the Conservative route.',
        real: 'The Primrose League had over a million members by 1910, a large share of them women, and gave Conservative women political work long before they had the vote. Cazalet-Keir and Tate came into Conservative politics from wealthy families after the war.',
        check: 'unchecked', facts: ['primrose-league', 'cazalet-early'],
        choices: [
          { label: 'Write the speeches, and learn the machine', effects: 'cap+3 order+2 fav+3', historical: true,
            result: 'You discover that the dames who run the habitations know every voter in the district, and what each of them wants. It is a political education the ILP never gave you.',
            diary: 'The dames know every voter.' },
          { label: 'Laugh with the nephew', effects: 'press+2 fav-2 temper+1',
            result: 'He is charming and useless. Your employer notices you laughing, and is cooler for a month.',
            diary: 'Laughed with him. A cool month.' },
          { label: 'Ask the League why women cannot vote', effects: 'state+1 temper+2 @aster+2',
            result: 'The committee is shocked, then interested. Several of the dames are secret suffragists. One of them is an American, Mrs Aster, who says she will be in Parliament one day. Everyone laughs.',
            diary: 'Mrs Aster says she\'ll be in Parliament. Laughter.' },
        ] },

      { id: 'welfare-1916', year: 1916, title: 'The welfare supervisor', if: '!route-tory',
        venue: { plate: 'mill', label: 'A National Shell Filling Factory' },
        text: '1916. You are a welfare supervisor in a shell-filling factory: eight thousand women handling TNT, their skin turned yellow, the canaries, the papers call them. Some are dying of toxic jaundice. The management wants production; the Ministry of Munitions wants production and welfare both. A girl collapsed on the line this morning. The doctor says she should not come back. She says she needs the money.',
        basis: 'The work of women welfare supervisors in munitions factories during the First World War, and TNT poisoning among the "munitionettes" or "canaries".',
        real: 'Hundreds of thousands of women worked in munitions; TNT poisoning turned their skin yellow, and toxic jaundice killed over a hundred. The Ministry of Munitions appointed women welfare supervisors. Many future Conservative and Labour women politicians did war welfare work.',
        check: 'research', facts: ['munitions-tnt'],
        choices: [
          { label: 'Send her home on full pay, and fight for it', effects: 'state+2 steel+2 fav-1 rep+2', historical: true,
            result: 'You bully the manager into paying her for a month. Then you write to the Ministry with every case on your list. Masks and rotation come in, slowly.',
            diary: 'Full pay. Masks, slowly.' },
          { label: 'Let her work: she needs the money', effects: 'order+1 money+1',
            result: 'She goes back on the line. Six weeks later she is in hospital. You keep her name on a card in your desk for the rest of your life.',
            diary: 'Her name on a card.' },
          { label: 'Go to the Ministry over the manager\'s head', effects: 'cap+2 fav+3 order+1',
            result: 'A Ministry inspector comes the next week and closes the worst shed. The manager never forgives you; the Ministry offers you a post.',
            diary: 'The worst shed closed. A Ministry post offered.' },
        ] },

      { id: 'plymouth-1919', year: 1919, title: 'Plymouth', if: '!route-tory',
        venue: { plate: 'city', label: 'The Barbican, Plymouth' },
        text: 'November 1919. Mrs Nancy Aster is standing for Plymouth Sutton, the seat her husband had to leave when he inherited his father\'s peerage. If she wins she will be the first woman to take a seat in the Commons. She campaigns in a black costume and a tricorn hat, rides through the fish market, and answers hecklers with jokes. She wants you to run her women\'s committee. Her opponent is a Labour man.',
        basis: 'Nancy Astor\'s by-election victory at Plymouth Sutton on 28 November 1919; she took her seat on 1 December 1919, the first woman to sit in the Commons.',
        real: 'Nancy Astor won the Plymouth Sutton by-election on 28 November 1919, after her husband Waldorf succeeded to his father\'s viscountcy, and took her seat on 1 December. Constance Markievicz, elected in 1918, never sat.',
        check: 'research', facts: ['astor-1919'],
        choices: [
          { label: 'Run her women\'s committee', effects: 'cap+3 fav+4 press+2 @aster+10', historical: true,
            result: 'You organise the wives of Devonport\'s sailors street by street. She wins by over five thousand, and takes you to Westminster to watch her walk up the floor of the House between two Members.',
            diary: 'Mrs Aster won. Watched her walk up the floor.' },
          { label: 'Help her, but quietly prefer the Labour man', effects: 'state+2 loyalty-2 @aster+2',
            result: 'You do the work and vote Labour. She guesses, and does not mind: she says she likes people who think.',
            diary: 'Worked for her, voted Labour. She guessed.' },
          { label: 'Turn her down: the Tories are not your party', effects: 'state+2 @aster-3 -!route-tory !route-manchester set:city=Manchester set:seat=Middlesbrough_East set:party=Labour set:council=Manchester_City_Council',
            result: 'You go home to Manchester and the ILP. Mrs Aster sends you a signed photograph anyway.',
            diary: 'Home to Labour. A signed photograph.' },
        ] },

      { id: 'lcc-1922', year: 1922, title: 'The County Hall', if: '!route-tory',
        venue: { plate: 'whitehall', label: 'County Hall, Westminster Bridge' },
        text: 'March 1922. The Municipal Reformers, London\'s Conservatives, have asked you to stand for the London County Council, which runs the capital\'s schools, trams, asylums and housing from its new County Hall on the river. It is the biggest local government in the world, and its committees are where women can actually govern. Your ward is safe. The question is which committee to ask for.',
        basis: 'Women in London County Council politics: Thelma Cazalet was elected to the LCC as a Municipal Reformer in 1924 and served seven years, before entering Parliament in 1931.',
        real: 'Thelma Cazalet served on the LCC from 1924 to 1931, becoming an alderman. The LCC moved into its new County Hall in 1922. Many inter-war women MPs began in local government.',
        check: 'research', facts: ['cazalet-early'],
        choices: [
          { label: 'Education', effects: 'cap+3 state+2 order+1', historical: true,
            result: 'You sit on the education committee, visiting schools from Bermondsey to Hampstead. You learn that the same city runs schools that might be on different planets.',
            diary: 'Education. Bermondsey and Hampstead.' },
          { label: 'Housing', effects: 'state+3 cap+2',
            result: 'You sit on housing and fight for the new cottage estates beyond the city. Your own party thinks you are too keen.',
            diary: 'Housing. Too keen, they say.' },
          { label: 'Finance', effects: 'order+3 fav+4 money+2',
            result: 'You take finance, where the power is. The men on the committee are surprised that you read the estimates. Then they are alarmed.',
            diary: 'Finance. They are alarmed.' },
        ] },

      /* ═══════ Shared ═══════ */
      { id: 'influenza-1918', year: 1918, title: 'The influenza',
        venue: { plate: 'sickroom', label: 'A sickroom in {city}' },
        text: 'November 1918. The war is ending, and a new influenza is killing young people in their twenties in days, faster than the war did. The schools are closed, the undertakers have run out of coffins, and the doctors have nothing to give. Your neighbour\'s family are all down with it, three children and their mother, and nobody will go into the house.',
        basis: 'The influenza pandemic of 1918–19, which killed about 228,000 people in Britain, with its peak in the autumn of 1918.',
        real: 'The 1918–19 influenza pandemic killed about 228,000 people in Britain, unusually many of them young adults. Schools and cinemas closed in many towns. This scene is invented.',
        check: 'research', facts: ['influenza-1918'],
        choices: [
          { label: 'Go in and nurse them', effects: 'state+2 rep+2 health-3', historical: true,
            death: { chance: 0.03, text: 'You caught the influenza nursing your neighbours and died of pneumonia within four days, in November 1918, the week the war ended. You were 27.', headline: 'Influenza claims another' },
            result: 'You carry soup and coal for a fortnight. The youngest child dies; the rest live. You are ill for a week yourself, and get up.',
            diary: 'Nursed them. Lost the youngest.' },
          { label: 'Fetch the district nurse and stay away', effects: 'order+1 health+1',
            result: 'The nurse comes once a day; she has two hundred cases. Two of the children die.',
            diary: 'The nurse. Two hundred cases. Two children.' },
          { label: 'Organise the street to take turns', effects: 'cap+2 state+2 health-1',
            result: 'You draw up a rota: soup from one house, coal from another, a sitter at night. Nobody in the street dies who had a rota. You learn that organisation is a kind of kindness.',
            diary: 'The rota. Organisation is kindness.' },
        ] },
    ],
  };
})();
